mapper.select:
SELECT id, kind, title, revision, updated_at FROM knowledge_board
WHERE owner_id = #{owner}
AND id > #{cursor}
ORDER BY id LIMIT #{limit}

SELECT revision, title, created_at FROM knowledge_board_revision
WHERE owner_id = #{owner} AND board_id = #{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE knowledge_board SET title = #{board.title}, revision = #{board.revision},
  snapshot_json = #{json}, updated_at = #{board.updatedAt}
WHERE owner_id = #{owner} AND id = #{board.id} AND revision = #{expected}
